AAA=
'@
$hashEsperado = '5b275ce313cfe52870e5c109e19605e3107788ae94d4f3c29f418485b5a48c83'
$temporario = Join-Path ([IO.Path]::GetTempPath()) ('ccbmusica-grupo-v42-' + [guid]::NewGuid().ToString('N'))
try {
    New-Item -Path $temporario -ItemType Directory -Force | Out-Null
    $arquivoZip = Join-Path $temporario 'grupo-v42.zip'
    $bytes = [Convert]::FromBase64String(($pacoteBase64 -replace '\s', ''))
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $hashAtual = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant()
    } finally {
        $sha.Dispose()
    }
    if ($hashAtual -ne $hashEsperado) {
        throw 'Arquivo do instalador corrompido: baixe novamente a V4.2.'
    }
    [IO.File]::WriteAllBytes($arquivoZip, $bytes)
    Expand-Archive -LiteralPath $arquivoZip -DestinationPath $temporario -Force
    $instalador = Join-Path $temporario 'instalar-grupo-avaliacoes-v4.ps1'
    $manifestoPath = Join-Path $temporario 'payload/manifest.json'
    if (-not (Test-Path -LiteralPath $manifestoPath -PathType Leaf) -or
        -not (Test-Path -LiteralPath $instalador -PathType Leaf)) {
        throw 'Pacote interno incompleto. Nenhuma alteracao realizada.'
    }
    $json = [IO.File]::ReadAllText($manifestoPath, [Text.Encoding]::UTF8)
    $parsed = ConvertFrom-Json -InputObject $json
    $total = 0
    foreach ($item in $parsed) {
        if ($item -is [System.Array]) {
            foreach ($sub in $item) { $total += 1 }
        } else { $total += 1 }
    }
    if ($total -ne 14) {
        throw "Manifesto interno invalido: esperado 14 operacoes, encontrado $total. Nenhum arquivo alterado."
    }
    Write-Host 'V4.2: 14 operacoes confirmadas. Validando arquivos do projeto...' -ForegroundColor Cyan
    & $instalador -Projeto $raiz
} finally {
    if (Test-Path -LiteralPath $temporario) {
        Remove-Item -LiteralPath $temporario -Recurse -Force -ErrorAction SilentlyContinue
    }
}
